import{_ as d,C as a,o as r,c as l,aj as e,E as c}from"./framework.js";const S=JSON.parse('{"title":"控制台：Google SC | Product / Console | Documentation","description":"控制台：Google SC in Kooboo: 接入 Google Search Console，完成身份验证后查看站点权限、验证站点、查看 Analytics，并提交 Sitemap。","frontmatter":{"title":"控制台：Google SC | Product / Console | Documentation","description":"控制台：Google SC in Kooboo: 接入 Google Search Console，完成身份验证后查看站点权限、验证站点、查看 Analytics，并提交 Sitemap。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/google-search-console.html"}]]},"headers":[],"relativePath":"zh/product/console/google-search-console.md","filePath":"product/console/google-search-console.md","lastUpdated":1780996899000}'),n={name:"zh/product/console/google-search-console.md"};function s(i,t,h,p,b,g){const o=a("DocImage");return r(),l("div",null,[t[0]||(t[0]=e('<h1 id="控制台-google-sc" tabindex="-1">控制台：Google SC <a class="header-anchor" href="#控制台-google-sc" aria-label="Permalink to &quot;控制台：Google SC&quot;">​</a></h1><blockquote><p>接入 Google Search Console，完成身份验证后查看站点权限、验证站点、查看 Analytics，并提交 Sitemap。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>Google SC</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/searchConsole</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/searchConsole</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>Google SC 是组织级入口。页面会先判断当前账号是否已经完成 Google 授权，再决定显示登录提示或站点列表。</p>',5)),c(o,{src:"/product/console/google-search-console-overview.png",alt:"控制台 Google Search Console 站点列表",width:"1120"}),t[1]||(t[1]=e('<h2 id="身份验证" tabindex="-1">身份验证 <a class="header-anchor" href="#身份验证" aria-label="Permalink to &quot;身份验证&quot;">​</a></h2><p>如果还没有完成 Google 授权，页面会显示提示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>要访问Google Search Console 数据请先完成身份验证</span></span></code></pre></div><p>点击 <code>Login</code> 后会跳转到后端返回的授权地址，授权回调地址使用当前页面地址。完成授权后再回到 Google SC 页面查看站点列表。</p><h2 id="站点列表" tabindex="-1">站点列表 <a class="header-anchor" href="#站点列表" aria-label="Permalink to &quot;站点列表&quot;">​</a></h2><p>授权完成后，页面显示站点表格：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Site</td><td>Search Console 站点 URL</td></tr><tr><td>Permission</td><td>权限级别，例如 <code>siteOwner</code>、<code>siteUnverifiedUser</code></td></tr><tr><td>操作</td><td>未验证站点显示 <code>Validation</code>；已验证站点显示 <code>Analytics</code> 和 <code>Sitemap</code></td></tr></tbody></table><p>当前前端代码中“添加站点”按钮处于注释状态，因此常规界面主要用于查看和管理已返回的站点列表。若你的环境额外开放添加入口，以实际界面为准。</p><h2 id="验证站点" tabindex="-1">验证站点 <a class="header-anchor" href="#验证站点" aria-label="Permalink to &quot;验证站点&quot;">​</a></h2><p>当站点权限为 <code>siteUnverifiedUser</code> 时，右侧会显示 <code>Validation</code>。</p><p>点击后前端会调用验证接口，并尝试刷新站点列表。验证通过后，该站点会切换到已验证状态，右侧显示 <code>Analytics</code> 和 <code>Sitemap</code>。</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>已验证站点点击 <code>Analytics</code> 会打开分析弹窗。</p><p>顶部筛选：</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>聚合方式</td><td><code>Auto</code>、<code>By Page</code>、<code>By Property</code></td></tr><tr><td>日期范围</td><td>默认最近 30 天</td></tr><tr><td><code>Search</code></td><td>按当前条件重新加载数据</td></tr></tbody></table><p>结果表格：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Clicks</td><td>点击数</td></tr><tr><td>CTR</td><td>点击率</td></tr><tr><td>Impressions</td><td>展示次数</td></tr><tr><td>Keys</td><td>Search Console 返回的 key 列表</td></tr></tbody></table><h2 id="sitemap" tabindex="-1">Sitemap <a class="header-anchor" href="#sitemap" aria-label="Permalink to &quot;Sitemap&quot;">​</a></h2><p>已验证站点点击 <code>Sitemap</code> 会打开 Sitemap 弹窗。</p><p>顶部 <code>Submit</code> 下拉按钮会列出当前站点可提交、且尚未提交的 Feed。选择后会提交 Sitemap 并刷新列表。</p><p>Sitemap 表格：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Path</td><td>Sitemap 路径</td></tr><tr><td>Last Submitted</td><td>最近提交时间</td></tr><tr><td>Last Downloaded</td><td>Google 最近下载时间</td></tr><tr><td>Error</td><td>错误数量</td></tr><tr><td>Warning</td><td>警告数量</td></tr></tbody></table><p>勾选已有 Sitemap 后可删除，删除前会弹确认。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>首次接入 Search Console</td><td>Google SC -&gt; Login -&gt; 授权完成 -&gt; 回到站点列表</td></tr><tr><td>验证站点</td><td>站点列表 -&gt; Validation -&gt; 刷新后确认权限状态</td></tr><tr><td>提交站点地图</td><td>Sitemap -&gt; Submit -&gt; 选择 Feed -&gt; 检查 Error / Warning</td></tr><tr><td>查看搜索表现</td><td>Analytics -&gt; 选择聚合方式与日期范围 -&gt; Search</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./domains.html">域名</a></td><td>Search Console 常依赖已接入域名</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/basic/seo.html">CMS：SEO 设置</a></td><td>站点级 SEO 设置</td></tr></tbody></table>',27))])}const u=d(n,[["render",s]]);export{S as __pageData,u as default};
